import React, { useCallback, useState } from "react";
import { StateContextValue } from "../../backend/GameState";

export type UIContextValue = {
  getUIState: (id: string) => any;
  setUIState: (id: string, value: any) => void;
};

export const UIContext = React.createContext<UIContextValue>({
  getUIState: (id: string) => null,
  setUIState: (id: string, value: any) => {},
});

export function useUIStateFromContext<T>(
  context: UIContextValue,
  key: string,
  initialValue: T,
): [T, (value: T) => void] {
  const currentValue = context.getUIState(key) ?? initialValue;
  const [stateValue, setStateValue] = useState<T>(currentValue);
  const setCurrentValue = useCallback(
    (value: T) => {
      setStateValue(value);
      context.setUIState(key, value);
    },
    [context, key, setStateValue],
  );

  return [stateValue as T, setCurrentValue];
}

export function useUIStateFromGameState<T>(
  contextRef: React.RefObject<StateContextValue>,
  key: string,
  initialValue: T,
): [T, (value: T) => void] {
  const currentValue =
    contextRef.current.options.savedUIState[key] ?? initialValue;
  const [stateValue, setStateValue] = useState<T>(currentValue);
  const setCurrentValue = useCallback(
    (value: T) => {
      setStateValue(value);
      contextRef.current.apply((state) => {
        state.options.savedUIState[key] = value;
        return state;
      });
    },
    [contextRef, key, setStateValue],
  );

  return [stateValue as T, setCurrentValue];
}
