import React, { useCallback, useMemo, useState } from "react";
import { StyleSheet, View } from "react-native";
import { StorylineStatus } from "../../backend/storylines/Storyline";
import { getSortedStorylines } from "../../backend/storylines/Storylines";
import Divider from "./Divider";
import { StorylineContainer } from "./StorylineContainer";
import { useGameState } from "./useGameState";

type StorylinesContainerProps = {
  onlyStorylineStatus?: StorylineStatus;
};

export default function StorylinesContainer(props: StorylinesContainerProps) {
  const [expandedStorylines, setExpandedStorylines] = useState({});
  const state = useGameState();
  const onlyStorylineStatus = props.onlyStorylineStatus;
  const setStorylineCallback = useCallback(
    (storylineName: string) => {
      const newStorylines = {
        ...expandedStorylines,
      };
      newStorylines[storylineName] = !expandedStorylines[storylineName];
      setExpandedStorylines(newStorylines);
    },
    [expandedStorylines],
  );

  const storylines = getSortedStorylines().filter(
    (storyline) =>
      !storyline.isHidden(state) &&
      (onlyStorylineStatus == null ||
        onlyStorylineStatus == storyline.getStatus(state)),
  );
  const storylineNameString = storylines
    .map((storyline) => storyline.name)
    .join(",");

  const storylineContainers = useMemo(
    () =>
      storylines.map((storyline) => {
        return (
          <StorylineContainer
            key={storyline.name}
            storyline={storyline}
            collapsed={!expandedStorylines[storyline.name]}
            onPressExpand={setStorylineCallback.bind(null, storyline.name)}
          />
        );
      }),
    [storylineNameString, expandedStorylines],
  );

  return useMemo(() => {
    if (storylines.length === 0) {
      return null;
    }
    return (
      <View>
        <View key={storylines[0].name}>{storylineContainers[0]}</View>
        {storylineContainers.slice(1).map((storylineContainer, idx) => {
          return (
            <View key={storylines[idx].name}>
              <Divider />
              {storylineContainer}
            </View>
          );
        })}
      </View>
    );
  }, [storylineNameString, storylineContainers]);
}

const styles = StyleSheet.create({});
